QUESTION_TYPES = ("choice", "fill", "solution")
QUESTION_TYPE_LABELS = {"choice": "选择题", "fill": "填空题", "solution": "解答题"}
WORKBENCH_EXCLUDED_SECTIONS = ("参考答案", "简明解析")
SUBQUESTION_HEADING_RE = re.compile(r"(?m)^#{3,6}\s+[（(]\s*\d+\s*[）)]")

# Some of the built-in prose templates are ordinary Python strings while the
# formula cards intentionally use raw strings.  Keep the API response clean
# for both cases: a doubled command slash (``\\\\le``) is not the same as the
# TeX command ``\\le``.  Matrix row breaks (``\\\\`` before a row's content)
# are deliberately left alone in formula cards.
_TEX_COMMAND_NAMES = (
    "begin|end|frac|dfrac|tfrac|sqrt|binom|left|right|mathrm|mathbf|mathit|"
    "text|operatorname|mathbb|mathsf|mathcal|mathscr|displaystyle|textstyle|"
    "scriptstyle|lim|sin|cos|tan|cot|sec|csc|arcsin|arccos|arctan|ln|log|exp|"
    "sum|prod|int|iint|iiint|partial|nabla|infty|to|sim|le|ge|leq|geq|leqslant|"
    "geqslant|ne|neq|in|notin|subset|subseteq|forall|exists|varnothing|emptyset|"
    "Longleftrightarrow|Longrightarrow|Longleftarrow|Rightarrow|Leftrightarrow|"
    "leftarrow|rightarrow|longleftarrow|longrightarrow|longleftrightarrow|xrightarrow|cdot|times|pm|mp|approx|asymp|nsim|gtrless|quad|qquad|det|"
    "lambda|xi|mu|alpha|beta|gamma|delta|theta|pi|Delta|Lambda|Phi|Omega|ell|eta|kappa|"
    "rho|psi|sigma|zeta|varphi|varepsilon|phi|boldsymbol|vec|bar|overline|underline|"
    "overbrace|underbrace|widehat|hat|check|tilde|dot|ddot|cdots|ldots|dots|"
    "vdots|ddots|prime|mid|middle|boxed|hspace|limits|substack|max|min|"
    "Big|big|bigl|bigr|bigg|Bigg|Bigl|Bigr|Biggl|Biggr|cup|cap|setminus|circ|"
    "perp|downarrow|uparrow|triangle|ker|pmod|mod"
)
_TEX_COMMAND_RE = re.compile(rf"(?<!\\)\\\\(?=(?:{_TEX_COMMAND_NAMES})(?![A-Za-z]))")
_TEX_LONG_ESCAPE_RE = re.compile(rf"(?<!\\)(?:\\\\){{2,}}(?=(?:{_TEX_COMMAND_NAMES})(?![A-Za-z]))")


def _normalize_template_prose(value: str) -> str:
    """Collapse accidental double escapes in one-line template guidance."""
    return str(value or "").replace("\\\\", "\\")


def _normalize_template_formula(value: str) -> str:
    """Normalize doubled TeX command escapes without destroying matrix rows."""
    formula = str(value or "")
    # A raw string copied through two serializers can contain four or more
    # slashes before a command.  Collapse only even runs; an odd run such as
    # ``\\\\\\left`` is an intentional array row break followed by a command.
    formula = _TEX_LONG_ESCAPE_RE.sub(lambda _match: "\\", formula)
    return _TEX_COMMAND_RE.sub(lambda _match: "\\", formula)


def _build_answer_structure(
    overview: str,
    framework: list[str],
    mistakes: list[str],
) -> list[dict[str, str]]:
    """Turn a detailed subtype guide into a paper-ready writing sequence."""
    steps = [str(item).strip() for item in framework if str(item).strip()]
    if not steps:
        return [
            {"label": "题型定位", "prompt": "先写清题目要证明或计算什么。", "content": overview},
            {"label": "条件核验", "prompt": "把定理或公式的使用条件逐项列出。", "content": "检查定义域、连续性、可导性和参数范围。"},
            {"label": "核心过程", "prompt": "按照题型的标准方法展开计算或证明。", "content": "每一步保留关键等式、变形依据和中间结论。"},
            {"label": "结论复核", "prompt": "最后回到题目要求，写出完整结论。", "content": "检查范围、符号、单位和充分必要性。"},
        ]
    middle = steps[2:-2] or steps[2:-1] or steps[2:]
    boundary = steps[-2] if len(steps) >= 4 else "检查参数边界、特殊点和需要分情况讨论的位置。"
    return [
        {
            "label": "题型定位",
            "prompt": "开头先说明目标，告诉阅卷人你准备使用哪条主线。",
            "content": overview,
        },
        {
            "label": "条件翻译",
            "prompt": "把题干中的文字和限制改写成可计算、可引用的数学条件。",
            "content": steps[0],
        },
        {
            "label": "定理核验",
            "prompt": "把能拿到定理分的前提写出来，不用‘显然’带过。",
            "content": steps[1] if len(steps) > 1 else steps[0],
        },
        {
            "label": "核心过程",
            "prompt": "按下面顺序逐步写，公式和关键理由不要省略。",
            "content": "\n".join(middle),
        },
        {
            "label": "边界与分支",
            "prompt": "处理参数临界值、端点、退化情形和多解分支，避免只覆盖一般情况。",
            "content": boundary,
        },
        {
            "label": "结论复核",
            "prompt": "收尾时把中间结论还原成题目要的答案，并主动检查高频失分点。",
            "content": f"{steps[-1]}{' ' + mistakes[0] if mistakes else ''}",
        },
    ]


def _topic(
    subtype_id: str,
    name: str,
    goal: str,
    conditions: str,
    method: str,
    check: str,
    signals: tuple[str, ...],
    memory_aid: str,
) -> dict[str, Any]:
    return {
        "id": subtype_id,
        "name": name,
        "summary": goal,
        "overview": f"本题型围绕{name}展开，核心任务是{goal}。作答时要把定理条件、目标形式和结论方向连成一条可核验的推理链。",
        "framework": [
            f"识别题型：看到与{name}有关的条件后，先把题目目标改写为“{goal}”。",
            f"核对前提：逐项确认{conditions}，不满足时先补构造或分情况讨论。",
            f"执行主线：{method}",
            f"收尾复核：{check}，再单独写出题目要求的结论。",
        ],
        "mistakes": [
            f"没有检查{conditions}，直接套用结论。",
            f"主步骤应当是“{method}”，却只写公式或跨过关键构造，导致得分点不可见。",
            f"结尾没有完成“{check}”，出现范围、符号、维数或充分必要性错误。",
        ],
        "memory_aid": memory_aid,
        "signals": signals,
    }


