def _detailed_topic(
    overview: str,
    framework: tuple[str, ...],
    formula_sheet: str,
    mistakes: tuple[str, ...],
    memory_aid: str,
) -> dict[str, Any]:
    return {
        "overview": overview,
        "framework": list(framework),
        "formula_sheet": formula_sheet,
        "mistakes": list(mistakes),
        "memory_aid": memory_aid,
    }


